class ROOT(object):
    """ROOT is a sentinel object representing the root target in a glom
    specification. It can be used with :class:`~glom.Let` to capture
    the original input data at any point in a specification.

    .. note::

       This is a singleton and does not need to be constructed.

    >>> from glom import glom, ROOT, Let
    >>> target = {'a': {'b': 1}, 'c': 2}
    >>> glom(target, Let('root', ROOT), 'root')
    {'a': {'b': 1}, 'c': 2}

    """
    __slots__ = ()

    def __repr__(self):
        return 'ROOT'

    def __reduce__(self):
        return (ROOT, ())


class Auto(object):
    """The ``Auto`` specifier type enables automatic handling of
    different target types based on their type.

    When used in a specification, ``Auto`` will dispatch to the
    appropriate handler based on the target's type.

    Args:
       default_spec: A spec to use when no type-specific handler 
          matches. Defaults to T.

    """
    def __init__(self, default_spec=T):
        self.default_spec = default_spec

    def glomit(self, target, scope):
        return scope[glom](target, self.default_spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default_spec is T:
            return '%s()' % cn
        return '%s(%r)' % (cn, self.default_spec)


class Fill(object):
    """The ``Fill`` specifier type fills in missing values in a 
    specification by applying a fill spec to extract or construct
    values for keys that don't exist in the target.

    Useful for ensuring all expected keys are present in output
    dictionaries, filling defaults for missing data.

    Args:
       fill_spec: The spec to apply when a key is missing.

    Example::

       >>> from glom import glom, Fill
       >>> target = {'a': 1}
       >>> spec = {'a': 'a', 'b': Fill(0)}
       >>> glom(target, spec)
       {'a': 1, 'b': 0}

    """
    def __init__(self, fill_spec):
        self.fill_spec = fill_spec

    def glomit(self, target, scope):
        # Fill is typically used within dict specs where it gets called
        # for missing keys. The actual filling logic is handled by
        # _handle_dict in core.py when this specifier is encountered.
        return scope[glom](target, self.fill_spec, scope)

    def __repr__(self):
        return 'Fill(%r)' % (self.fill_spec,)


class Iter(object):
    """The ``Iter`` specifier type explicitly iterates over its sub-spec.

    Similar to using a list but provides an explicit iterable wrapper.

    Args:
       spec: The spec to iterate over each item in the target.

    Example::

       >>> from glom import glom, Iter
       >>> target = [1, 2, 3]
       >>> glom(target, Iter('upper'), upper=str.upper)
       ['1', '2', '3']

    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        try:
            iterator = iterate(target)
        except Exception as e:
            raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                            % (target.__class__.__name__, Path(*scope[Path]), e))
        ret = []
        for i, t in enumerate(iterator):
            val = scope[glom](t, self.spec, scope)
            if val is SKIP:
                continue
            ret.append(val)
        return ret

    def __repr__(self):
        return 'Iter(%r)' % (self.spec,)


class Let(object):
    """The ``Let`` specifier type binds a name to a value within a
    scoped context, allowing later specs to reference previously
    computed values.

    Useful for extracting intermediate results and reusing them
    without recomputation.

    Args:
       name: The name to bind the value to (must be a valid Python identifier).
       val_spec: The spec to compute the value for *name*.
       next_spec: The spec to evaluate after binding the name.

    Example::

       >>> from glom import glom, Let
       >>> target = {'vals': [1, 2, 3]}
       >>> glom(target, Let('total', ('vals', sum)), ('total', lambda x: x * 2))
       12

    """
    def __init__(self, name, val_spec, next_spec):
        self.name = name
        self.val_spec = val_spec
        self.next_spec = next_spec

    def glomit(self, target, scope):
        val = scope[glom](target, self.val_spec, scope)
        new_scope = scope.new_child({self.name: val})
        return scope[glom](target, self.next_spec, new_scope)

    def __repr__(self):
        return 'Let(%r, %r, %r)' % (self.name, self.val_spec, self.next_spec)


class Invoke(object):
    """The ``Invoke`` specifier type calls a function/method with
    arguments extracted from the target via specs.

    Allows calling functions with dynamically determined arguments
    from the target data.

    Args:
       func: A callable to invoke. Can be a string path (like 'method_name')
             or a Spec/Spec-like object.
       args: Positional arguments as specs to extract from target.
       kwargs: Keyword arguments mapping names to specs.

    Example::

       >>> from glom import glom, Invoke
       >>> target = {'a': 1, 'b': 2}
       >>> glom(target, Invoke('sum', args=('a', 'b')))
       3

    """
    def __init__(self, func, args=None, kwargs=None):
        self.func = func
        self.args = tuple(args) if args else ()
        self.kwargs = dict(kwargs) if kwargs else {}

    def glomit(self, target, scope):
        # Resolve func
        if isinstance(self.func, str):
            func = scope[glom](target, self.func, scope)
        elif isinstance(self.func, Spec):
            func = scope[glom](target, self.func, scope)
        else:
            func = self.func

        # Resolve args
        resolved_args = []
        for arg_spec in self.args:
            resolved_args.append(scope[glom](target, arg_spec, scope))

        # Resolve kwargs
        resolved_kwargs = {}
        for k, v_spec in self.kwargs.items():
            resolved_kwargs[k] = scope[glom](target, v_spec, scope)

        return func(*resolved_args, **resolved_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        parts = [repr(self.func)]
        if self.args:
            parts.append('args=%r' % (self.args,))
        if self.kwargs:
            parts.append('kwargs=%r' % (self.kwargs,))
        return '%s(%s)' % (cn, ', '.join(parts))



